def transform(grid):
    h, w = len(grid), len(grid[0])

    # The solid edge row indicates the direction of gravity.
    wall_row = None
    for r in (0, h - 1):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            wall_row = r
            break
    if wall_row is None:
        wall_row = 0

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen or r == wall_row:
                continue
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))

    upward = wall_row == 0
    objects.sort(
        key=lambda obj: min(r for r, _ in obj[1]) if upward
        else -max(r for r, _ in obj[1])
    )

    out = [[0] * w for _ in range(h)]
    out[wall_row] = grid[wall_row][:]

    for color, cells in objects:
        dr = -1 if upward else 1
        shift = 0
        while True:
            next_shift = shift + dr
            blocked = False
            for r, c in cells:
                nr = r + next_shift
                if not (0 <= nr < h) or out[nr][c] != 0:
                    blocked = True
                    break
            if blocked:
                break
            shift = next_shift
        for r, c in cells:
            out[r + shift][c] = color

    return out
